#!/usr/bin/env bash
set -euo pipefail

PANEL_ROOT="/opt/wg-ui"
PAYLOAD_MARKER="__WG_UI_PAYLOAD_BASE64__"

log(){ echo "[install] $*"; }

require_root(){
  if [[ ${EUID} -ne 0 ]]; then
    echo "Run with sudo: sudo bash install.sh"
    exit 1
  fi
}

check_ubuntu(){
  if [[ ! -f /etc/os-release ]]; then
    echo "Cannot detect OS"
    exit 1
  fi
  . /etc/os-release
  if [[ "${ID:-}" != "ubuntu" ]]; then
    echo "This installer supports Ubuntu only"
    exit 1
  fi
}

install_packages(){
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -y
  apt-get install -y wireguard wireguard-tools nginx php-fpm php-cli php-mbstring php-xml php-curl php-zip php-opcache qrencode unzip curl jq rsync openssl iptables ca-certificates
}

extract_embedded_project(){
  local target="$1" tmp_archive
  tmp_archive="$(mktemp)"

  awk -v marker="$PAYLOAD_MARKER" '
    $0 == marker {found=1; next}
    found {print}
  ' "$0" | base64 -d > "$tmp_archive"

  if [[ ! -s "$tmp_archive" ]]; then
    echo "Embedded payload is empty or corrupted" >&2
    exit 1
  fi

  mkdir -p "$target"
  tar -xzf "$tmp_archive" -C "$target"
  rm -f "$tmp_archive"
}

prepare_project_files(){
  local script_dir
  script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

  if [[ -d "${script_dir}/app" ]]; then
    log "Using local project files"
    rsync -a --delete --exclude '.git' "${script_dir}/" "${PANEL_ROOT}/"
    return
  fi

  log "Using embedded project payload"
  rm -rf "${PANEL_ROOT}"
  extract_embedded_project "${PANEL_ROOT}"
}

install_root_wrapper(){
  install -m 0750 -o root -g root "${PANEL_ROOT}/scripts/root-wrapper.sh" /usr/local/bin/wg-panel-root-wrapper.sh
}

run_wireguard_install(){
  chmod +x "${PANEL_ROOT}/scripts/wireguard-install.sh"
  "${PANEL_ROOT}/scripts/wireguard-install.sh" install
}

run_panel_install(){
  chmod +x "${PANEL_ROOT}/scripts/start2.sh"
  (cd "${PANEL_ROOT}" && ./scripts/start2.sh)
}

print_summary(){
  local ip login password conf
  ip="$(curl -4fsS https://api.ipify.org || hostname -I | awk '{print $1}')"
  login="$(jq -r '.login' ${PANEL_ROOT}/storage/users/admin.json)"
  password="$(awk -F': ' '/Password:/{print $2}' /root/wg-ui-credentials.txt 2>/dev/null || echo 'See /root/wg-ui-credentials.txt')"
  conf="/etc/wireguard/clients/test-client.conf"

  echo
  echo "========================================="
  echo "WG UI installed successfully"
  echo "Panel: http://${ip}/"
  echo "Login: ${login}"
  echo "Password: ${password}"
  echo "Client config: ${conf}"
  echo "========================================="
}

require_root
check_ubuntu
install_packages
prepare_project_files
install_root_wrapper
run_wireguard_install
run_panel_install
print_summary

exit 0
__WG_UI_PAYLOAD_BASE64__
